/**
 * Repeatable schema migrations.
 *
 * Every migration is applied inside a transaction and recorded in
 * `schema_migrations`, so running them repeatedly is safe. All tables of the
 * data model decided in Issue #1 (contract comment #1) exist from the start so
 * that follow-up worksheet/cell work only adds behavior, not schema churn.
 *
 * @typedef {{ id: string, sql: string }} Migration
 */

/** @type {Migration[]} */
export const MIGRATIONS = [
  {
    id: '001_initial_schema',
    sql: `
      CREATE TABLE IF NOT EXISTS workbooks (
        id          TEXT PRIMARY KEY,
        name        TEXT NOT NULL,
        created_at  TEXT NOT NULL,
        updated_at  TEXT NOT NULL
      );

      CREATE TABLE IF NOT EXISTS worksheets (
        id             TEXT PRIMARY KEY,
        workbook_id    TEXT NOT NULL REFERENCES workbooks(id) ON DELETE CASCADE,
        name           TEXT NOT NULL,
        position       INTEGER NOT NULL,
        row_count      INTEGER NOT NULL,
        col_count      INTEGER NOT NULL,
        last_active    INTEGER NOT NULL DEFAULT 0,
        last_selection TEXT
      );

      CREATE INDEX IF NOT EXISTS idx_worksheets_workbook
        ON worksheets (workbook_id, position);

      CREATE TABLE IF NOT EXISTS cells (
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        row          INTEGER NOT NULL,
        col          INTEGER NOT NULL,
        raw          TEXT NOT NULL,
        PRIMARY KEY (worksheet_id, row, col)
      );

      CREATE TABLE IF NOT EXISTS validation_rules (
        id           TEXT PRIMARY KEY,
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        kind         TEXT NOT NULL,
        range        TEXT NOT NULL,
        params       TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_validation_rules_worksheet
        ON validation_rules (worksheet_id);

      CREATE TABLE IF NOT EXISTS filters (
        id           TEXT PRIMARY KEY,
        worksheet_id TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        range        TEXT NOT NULL,
        column_specs TEXT NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_filters_worksheet
        ON filters (worksheet_id);

      CREATE TABLE IF NOT EXISTS pivots (
        id                   TEXT PRIMARY KEY,
        source_worksheet_id  TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        source_range         TEXT NOT NULL,
        config               TEXT NOT NULL,
        result_worksheet_id  TEXT NOT NULL REFERENCES worksheets(id) ON DELETE CASCADE,
        last_result          TEXT,
        stale                INTEGER NOT NULL DEFAULT 0
      );

      CREATE INDEX IF NOT EXISTS idx_pivots_source_worksheet
        ON pivots (source_worksheet_id);

      CREATE INDEX IF NOT EXISTS idx_pivots_result_worksheet
        ON pivots (result_worksheet_id);
    `,
  },
];

